func validateSchema(schema, root map[string]any, value any, path string) error {
	if ref, ok := schema["$ref"].(string); ok {
		name := ref[len("#/$defs/"):]
		defs, _ := root["$defs"].(map[string]any)
		resolved, ok := defs[name].(map[string]any)
		if !ok {
			return fmt.Errorf("%s: unresolved schema reference %s", path, ref)
		}
		return validateSchema(resolved, root, value, path)
	}
	if branches, ok := schema["anyOf"].([]any); ok {
		for _, branch := range branches {
			if validateSchema(branch.(map[string]any), root, value, path) == nil {
				return nil
			}
		}
		return fmt.Errorf("%s: value does not match any allowed schema", path)
	}
	if expected, ok := schema["const"]; ok && !equalJSON(expected, value) {
		return fmt.Errorf("%s: value must equal %v", path, expected)
	}
	if values, ok := schema["enum"].([]any); ok {
		matched := false
		for _, expected := range values {
			if equalJSON(expected, value) {
				matched = true
				break
			}
		}
		if !matched {
			return fmt.Errorf("%s: value is not in the allowed set", path)
		}
	}
	typeName, _ := schema["type"].(string)
	switch typeName {
	case "null":
		if value != nil {
			return fmt.Errorf("%s: expected null", path)
		}
	case "boolean":
		if _, ok := value.(bool); !ok {
			return fmt.Errorf("%s: expected boolean", path)
		}
	case "string":
		text, ok := value.(string)
		if !ok {
			return fmt.Errorf("%s: expected string", path)
		}
		if min, ok := number(schema["minLength"]); ok && float64(len([]rune(text))) < min {
			return fmt.Errorf("%s: string is too short", path)
		}
		if max, ok := number(schema["maxLength"]); ok && float64(len([]rune(text))) > max {
			return fmt.Errorf("%s: string is too long", path)
		}
		if pattern, ok := schema["pattern"].(string); ok {
			matched, err := regexp.MatchString(pattern, text)
			if err != nil || !matched {
				return fmt.Errorf("%s: string does not match %s", path, pattern)
			}
		}
	case "integer", "number":
		n, ok := number(value)
		if !ok || (typeName == "integer" && n != float64(int64(n))) {
			return fmt.Errorf("%s: expected %s", path, typeName)
		}
		if min, ok := number(schema["minimum"]); ok && n < min {
			return fmt.Errorf("%s: number is below minimum", path)
		}
		if max, ok := number(schema["maximum"]); ok && n > max {
			return fmt.Errorf("%s: number is above maximum", path)
		}
	case "array":
		items, ok := value.([]any)
		if !ok {
			return fmt.Errorf("%s: expected array", path)
		}
		if min, ok := number(schema["minItems"]); ok && float64(len(items)) < min {
			return fmt.Errorf("%s: array has too few items", path)
		}
		if max, ok := number(schema["maxItems"]); ok && float64(len(items)) > max {
			return fmt.Errorf("%s: array has too many items", path)
		}
		if child, ok := schema["items"].(map[string]any); ok {
			for index, item := range items {
				if err := validateSchema(child, root, item, fmt.Sprintf("%s[%d]", path, index)); err != nil {
					return err
				}
			}
		}
	case "object":
		object, ok := value.(map[string]any)
		if !ok {
			return fmt.Errorf("%s: expected object", path)
		}
		properties, _ := schema["properties"].(map[string]any)
		if required, ok := schema["required"].([]any); ok {
			for _, raw := range required {
				name := raw.(string)
				if _, exists := object[name]; !exists {
					return fmt.Errorf("%s.%s: required property is missing", path, name)
				}
			}
		}
		for name, childValue := range object {
			if child, exists := properties[name].(map[string]any); exists {
				if err := validateSchema(child, root, childValue, path+"."+name); err != nil {
					return err
				}
				continue
			}
			if schema["additionalProperties"] == false {
				return fmt.Errorf("%s.%s: additional property is not allowed", path, name)
			}
			if child, ok := schema["additionalProperties"].(map[string]any); ok {
				if err := validateSchema(child, root, childValue, path+"."+name); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

func number(value any) (float64, bool) {
	switch value := value.(type) {
	case float64:
		return value, true
	case float32:
		return float64(value), true
	case int:
		return float64(value), true
	case int64:
		return float64(value), true
	case json.Number:
		number, err := value.Float64()
		return number, err == nil
	default:
		return 0, false
	}
}

func equalJSON(left, right any) bool {
	leftNumber, leftIsNumber := number(left)
	rightNumber, rightIsNumber := number(right)
	if leftIsNumber || rightIsNumber {
		return leftIsNumber && rightIsNumber && leftNumber == rightNumber
	}
	return fmt.Sprint(left) == fmt.Sprint(right)
}
